import json
import logging
from flask import Flask, request, jsonify
from jinja2 import Environment, BaseLoader, select_autoescape

app = Flask(__name__)
logger = logging.getLogger(__name__)

# IoT device message template registry
TEMPLATE_REGISTRY = {
    "temperature": "Device {{device_id}} reported temperature: {{value}}°C",
    "humidity": "Device {{device_id}} reported humidity: {{value}}%",
    "alert": "ALERT from {{device_id}}: {{message}}"
}

# Jinja2 environment for rendering device messages
jinja_env = Environment(
    loader=BaseLoader(),
    autoescape=select_autoescape()
)

def resolve_template(msg_type, custom_template=None):
    """Resolve template - uses registry or allows custom device templates."""
    if custom_template:
        return custom_template
    return TEMPLATE_REGISTRY.get(msg_type, "Unknown message from {{device_id}}")

def render_device_message(template_str, context):
    """Render a device message using Jinja2 template engine."""
    template = jinja_env.from_string(template_str)
    return template.render(**context)

def log_rendered_message(rendered, device_id):
    """Persist rendered message to device log file."""
    log_path = f"/var/log/iot/{device_id}.log"
    try:
        with open(log_path, 'a') as f:
            f.write(rendered + '\n')
    except IOError as e:
        logger.warning(f"Could not write to {log_path}: {e}")

@app.route('/api/v1/device/message', methods=['POST'])
def handle_device_message():
    """Handle incoming IoT device messages via MQTT-HTTP bridge."""
    try:
        payload = request.get_json(force=True)
    except Exception:
        return jsonify({"error": "Invalid JSON"}), 400

    device_id = payload.get('device_id', 'unknown')
    msg_type = payload.get('type', 'generic')
    value = payload.get('value', '')
    message = payload.get('message', '')
    custom_template = payload.get('template', None)

    # Build context for template rendering
    context = {
        'device_id': device_id,
        'value': value,
        'message': message,
        'type': msg_type
    }

    # Resolve and render template
    template_str = resolve_template(msg_type, custom_template)
    rendered = render_device_message(template_str, context)

    # Log the rendered message
    log_rendered_message(rendered, device_id)

    return jsonify({
        "status": "processed",
        "rendered": rendered,
        "device_id": device_id
    }), 200

@app.route('/api/v1/device/batch', methods=['POST'])
def handle_batch_messages():
    """Process batch of device messages."""
    try:
        payload = request.get_json(force=True)
    except Exception:
        return jsonify({"error": "Invalid JSON"}), 400

    messages = payload.get('messages', [])
    results = []

    for msg in messages:
        device_id = msg.get('device_id', 'unknown')
        msg_type = msg.get('type', 'generic')
        custom_template = msg.get('template', None)
        context = {
            'device_id': device_id,
            'value': msg.get('value', ''),
            'message': msg.get('message', ''),
            'type': msg_type
        }
        template_str = resolve_template(msg_type, custom_template)
        rendered = render_device_message(template_str, context)
        log_rendered_message(rendered, device_id)
        results.append({"device_id": device_id, "rendered": rendered})

    return jsonify({"status": "batch_processed", "results": results}), 200


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
